import {chromium} from '@playwright/test';import fs from 'node:fs/promises';import assert from 'node:assert/strict';import {KEY,scenarioState,makeTask} from '../src/model.js';
const dir='检查记录/全站查缺补漏_20261022';await fs.mkdir(dir+'/优化后',{recursive:true});const browser=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true,args:['--no-proxy-server']}),p=await browser.newPage(),results=[],errors=[];p.setDefaultTimeout(7000);p.setDefaultNavigationTimeout(25000);p.on('pageerror',e=>errors.push(e.message));
async function load(route,s='PT05',width=1440,lang='zh'){await p.setViewportSize({width,height:width<720?844:1000});await p.goto('http://127.0.0.1:5184/plan',{waitUntil:'domcontentloaded'});await p.evaluate(({s,k,lang})=>{localStorage.setItem(k,JSON.stringify(s));localStorage.setItem('career-prototype-language',lang);localStorage.setItem('career-prototype-operation-guide-v1',JSON.stringify({enabled:false,neverPrompt:true}));},{s:typeof s==='string'?scenarioState(s):s,k:KEY,lang});await p.goto('http://127.0.0.1:5184'+route,{waitUntil:'domcontentloaded'});await p.locator('.page-surface').waitFor();await p.addStyleTag({content:'*,*::before,*::after{animation:none!important;transition:none!important}'});}
const state=()=>p.evaluate(k=>JSON.parse(localStorage.getItem(k)),KEY);
async function shot(name,selector){const el=p.locator(selector);await el.evaluate(e=>e.scrollIntoView({block:'start'}));await p.screenshot({path:dir+'/优化后/'+name+'-视口.png'});const v=p.viewportSize(),b=await el.boundingBox();await p.setViewportSize({width:v.width,height:Math.ceil(b.height+650)});const style=await p.addStyleTag({content:'.flow-progress{visibility:hidden!important}'});await el.screenshot({path:dir+'/优化后/'+name+'-板块.png'});await style.evaluate(e=>e.remove());await p.setViewportSize(v);}
async function check(name,fn){try{await fn();results.push({name,status:'pass'});console.log('PASS',name);}catch(e){results.push({name,status:'fail',error:e.message});console.log('FAIL',name,e.message.slice(0,700));await p.screenshot({path:dir+'/失败-'+results.length+'.png'});}}
try{
await check('检索识别前端和未知方向；示例只填草稿，确认后才展示来源',async()=>{await load('/assistant?tab=自然语言检索','PT01');await shot('1440-检索起点','.research-search');await p.getByRole('button',{name:'想了解前端开发',exact:true}).click();assert.equal((await state()).searchFilters.searched,false);await p.getByRole('button',{name:'生成模拟筛选草稿',exact:true}).click();assert.equal(await p.getByLabel('方向',{exact:true}).inputValue(),'frontend');assert.equal(await p.locator('.research-result-list').count(),0);await p.getByRole('button',{name:'确认筛选并检索（模拟）',exact:true}).click();assert.match(await p.locator('.research-result-list').innerText(),/前端开发/);assert.doesNotMatch(await p.locator('.research-result-list').innerText(),/数据分析/);await shot('1440-检索结果','.research-search');await p.getByLabel('描述需求',{exact:true}).fill('想做游戏');await p.getByRole('button',{name:'生成模拟筛选草稿',exact:true}).click();assert.equal(await p.getByLabel('方向',{exact:true}).inputValue(),'any');await p.getByRole('button',{name:'保存搜索条件，不开通知',exact:true}).click();assert.equal((await state()).presets[0].notifications,false);await p.locator('.saved-searches>summary').click();await p.getByRole('button',{name:'载入并修改',exact:true}).click();assert.equal(await p.getByLabel('方向',{exact:true}).inputValue(),'any');assert.equal(await p.locator('.research-result-list').count(),0);});
await check('空检索报错可恢复，私有和无数据源结果分开',async()=>{await load('/assistant?tab=自然语言检索');await p.getByRole('button',{name:'生成模拟筛选草稿',exact:true}).click();assert.equal(await p.getByRole('alert').count(),1);await p.getByLabel('描述需求',{exact:true}).fill('数据分析');await p.getByRole('button',{name:'生成模拟筛选草稿',exact:true}).click();await p.getByLabel('检索资料层',{exact:true}).selectOption('本人私有研究卡');await p.getByRole('button',{name:'确认筛选并检索（模拟）',exact:true}).click();assert.equal(await p.locator('.research-result-list>article').count(),1);await p.getByLabel('检索资料层',{exact:true}).selectOption('获准岗位（无数据源）');await p.getByRole('button',{name:'确认筛选并检索（模拟）',exact:true}).click();assert.equal(await p.locator('.research-result-list>article').count(),0);assert.match(await p.locator('.research-result-list').innerText(),/没有获准/);});
await check('旧比较ID不崩溃，仍能选择有效方向继续比较',async()=>{const s=scenarioState('PT05');s.compare=['data','removed-career'];await load('/careers?tab=比较',s);assert.match(await p.locator('main').innerText(),/旧方向已不可用/);await p.getByRole('checkbox',{name:'运维工程',exact:false}).check();assert.equal(await p.locator('#comparison-result table th').count(),3);assert.match(await p.locator('#comparison-result').innerText(),/运维工程/);});
await check('任务草稿和最新自检形成完整闭环，复盘始终带当前taskId',async()=>{const s=scenarioState('PT06');s.tasks.push({...makeTask(s,{title:'另一已完成行动（合成）',purpose:'另一个问题',hours:0}),id:'another',status:'完成',completed:true,note:'另一个记录'});await load('/work/task-demo?tab=尝试与反馈',s);await shot('1440-任务写作','.quality-task-layout');await p.getByLabel('产物文本（每次提交形成独立版本）',{exact:true}).fill('合成产物：问题清单、处理理由、描述统计和限制说明');await p.getByLabel('本人贡献',{exact:true}).fill('本人整理了问题清单');await p.getByRole('button',{name:'提交为 v2',exact:true}).click();await p.getByRole('button',{name:'记录本人自检（非实核）',exact:true}).last().click();await p.goto('http://127.0.0.1:5184/work/task-demo?tab=完成回执',{waitUntil:'domcontentloaded'});await p.locator('.task-readiness').waitFor();assert.equal(await p.locator('.task-readiness li').count(),5);await shot('1440-完成条件','.task-readiness');await p.getByRole('button',{name:'去核对标准',exact:true}).click();assert.equal(await p.locator('#task-standard-confirmation').evaluate(e=>document.activeElement===e),true);await p.locator('#task-standard-confirmation').check();await p.getByRole('button',{name:'记录有限范围完成',exact:true}).click();assert.equal((await state()).tasks[0].completed,true);await p.getByRole('button',{name:'稍后确认，先复盘',exact:true}).click();assert.equal(await p.getByLabel('关联实际任务',{exact:true}).inputValue(),'task-demo');});
await check('计划锚点在有任务时存在，依赖出口定位实际行动区',async()=>{await load('/plan#weekly-actions');const el=p.locator('#weekly-actions');assert.equal(await el.count(),1);const b=await el.boundingBox();assert.ok(b.y<1000&&b.y+b.height>0);await load('/plan#%');assert.equal(await p.locator('.page-surface').isVisible(),true);});
await check('学习短体验与综合项目默认范围不同，恢复阅读不新建任务',async()=>{await load('/learning?tab=短体验&unit=quality','PT01');assert.equal(await p.getByLabel('数据质量小项目的实践范围',{exact:true}).inputValue(),'最小范围');await load('/learning?tab=综合项目&unit=quality','PT01');assert.equal(await p.getByLabel('数据质量小项目的实践范围',{exact:true}).inputValue(),'标准范围');await p.getByRole('button',{name:'选择范围并开始预检',exact:true}).click();assert.equal((await state()).tasks.length,0);assert.equal((await state()).taskDraft.hours,4);const s=scenarioState('PT05');s.reading.quality={chapter:2,version:1};await load('/learning?collection=我的学习',s);await shot('1440-继续学习','.library-results');await p.getByRole('button',{name:'恢复这个阅读位置',exact:true}).click();assert.equal(await p.locator('dialog[open]').count(),1);assert.equal((await state()).tasks.length,1);});
await check('求职事件新增与修订保留历史及状态，不再追加重复事实',async()=>{await load('/careers?tab=我的机会');assert.match(await p.locator('.opportunity-content').innerText(),/保存的是哪一份工作/);await p.getByRole('button',{name:'记录本人申请 / 面试 / 结果',exact:true}).click();await p.getByLabel('本人笔记',{exact:true}).fill('原始笔记（合成）');await p.getByRole('button',{name:'保存本人事件',exact:true}).click();assert.equal((await state()).events.length,1);assert.equal(await p.locator('.application-timeline').count(),1);await p.getByRole('button',{name:'修订这条事件',exact:true}).click();await p.getByLabel('本人笔记',{exact:true}).fill('已纠正笔记（合成）');await p.getByRole('button',{name:'保存事件修订',exact:true}).click();const s=await state();assert.equal(s.events.length,1);assert.equal(s.events[0].version,2);assert.equal(s.events[0].history[0].note,'原始笔记（合成）');assert.equal(s.jobs[0].status,'准备');assert.equal(s.tasks.length,1);await shot('1440-事件修订','.opportunity-detail');});
await check('站内提醒承接同一对象且尊重复盘开关，查看受阻不改状态',async()=>{const s=scenarioState('PT05');s.tasks[0].status='受阻';s.tasks.push({...makeTask(s,{title:'已完成待复盘（合成）',purpose:'记录',hours:0}),id:'done',status:'完成',completed:true});await load('/settings',s);await p.locator('.workspace-utilities>summary').click();await p.getByRole('button',{name:'站内提醒',exact:true}).click();assert.equal(await p.getByRole('link',{name:'已完成，待留下一次复盘：已完成待复盘（合成）',exact:true}).count(),1);await p.getByRole('button',{name:'继续处理受阻任务：数据质量小项目（合成示例）',exact:true}).click();assert.equal((await state()).tasks[0].status,'受阻');assert.match(p.url(),/task=task-demo/);s.notifications=false;await load('/settings',s);await p.locator('.workspace-utilities>summary').click();await p.getByRole('button',{name:'站内提醒',exact:true}).click();assert.equal(await p.locator('dialog[open]').getByRole('link',{name:/已完成，待留下一次复盘/}).count(),0);});
await check('新界面手机、中英文与长输入无横向溢出，主要控件可操作',async()=>{for(const [name,route,s,lang,selector]of [['390-检索','/assistant?tab=自然语言检索','PT01','zh','.research-search'],['390-检索英文','/assistant?tab=自然语言检索','PT01','en','.research-search'],['390-任务写作','/work/task-demo?tab=尝试与反馈','PT06','zh','.quality-task-layout'],['390-完成条件','/work/task-demo?tab=完成回执','PT06','zh','.task-readiness'],['390-学习继续','/learning?collection=我的学习','PT05','zh','.library-results']]){await load(route,s,390,lang);assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);await shot(name,selector);if(lang==='en')assert.equal((await p.locator(selector).innerText()).match(/[\u4e00-\u9fff]+/g),null);}});
assert.deepEqual(errors,[]);results.push({name:'浏览器运行时错误',status:'pass',count:0});
}finally{await fs.writeFile(dir+'/优化浏览器验收.json',JSON.stringify({results,errors},null,2));await browser.close();}if(results.some(r=>r.status==='fail'))process.exitCode=1;
